from openpyxl import load_workbook
from openpyxl.styles import Alignment
import re

def process_data():
    # Load the workbook and select the 'DATA' sheet
    wb = load_workbook('input.xlsx')
    data_sheet = wb['DATA']
    combined_sheet = wb.create_sheet('combined')

    # Copy the header row
    for col in range(1, data_sheet.max_column + 1):
        combined_sheet.cell(row=1, column=col, value=data_sheet.cell(row=1, column=col).value)

    # Group rows by the value in column H (ComboKey)
    grouped_rows = {}
    for row in data_sheet.iter_rows(min_row=2, values_only=True):
        combo_key = row[7]  # Column H is index 7 (0-based)
        if combo_key not in grouped_rows:
            grouped_rows[combo_key] = {
                'material': row[0],
                'description': row[1],
                'number': row[2],
                'key': row[3],
                'product': row[4],
                'ws': row[5],
                'um': row[6],
                'combo_key': combo_key,
                'data': {}
            }
        # Process data columns (columns I to R)
        for col_idx in range(8, data_sheet.max_column + 1):
            col_letter = chr(65 + col_idx - 1)
            value = row[col_idx]
            if value is not None:
                if col_letter in ['I', 'J', 'K', 'L', 'M', 'N', 'O', 'P', 'Q', 'R']:
                    # Format values in columns I:R to 2 decimals, no commas, 0s as blanks
                    if value == 0:
                        grouped_rows[combo_key]['data'][col_letter] = ''
                    else:
                        grouped_rows[combo_key]['data'][col_letter] = f"{value:.2f}"
                else:
                    # Preserve exact formatting for columns A:R (excluding I:R)
                    grouped_rows[combo_key]['data'][col_letter] = value

    # Write the grouped data to the 'combined' sheet
    row_idx = 2
    for combo_key, group in grouped_rows.items():
        # Write the header row
        for col in range(1, data_sheet.max_column + 1):
            combined_sheet.cell(row=row_idx, column=col, value=group['data'].get(chr(65 + col - 1), ''))
        row_idx += 1

    # Save the workbook
    wb.save('output.xlsx')

