from openpyxl import load_workbook
from openpyxl.styles import Alignment, Font
import re

def process_sheet(wb, sheet_name='Sheet1'):
    wb = load_workbook('input.xlsx')
    sheet = wb[sheet_name]

    # Ensure calculation is automatic
    sheet.sheet_state = 'visible'

    # Convert any text-stored formulas back to formulas
    for row in sheet.iter_rows():
        for cell in row:
            if cell.data_type == 'f' and cell.value is None:
                cell.value = f"={cell.coordinate}"

    # Set calculation to automatic
    sheet.sheet_state = 'visible'

    # Recalculate all formulas
    sheet.calculate()

    # Round numbers in columns D-F to one decimal place
    for row in sheet.iter_rows(min_col=4, max_col=6):
        for cell in row:
            if cell.data_type == 'n':
                cell.value = round(cell.value, 1)

    # Apply number formatting to columns D-F
    for row in sheet.iter_rows(min_col=4, max_col=6):
        for cell in row:
            if cell.data_type == 'n':
                cell.number_format = '0.0'

    # Identify blocks of data separated by blank rows
    blocks = []
    current_block = []
    for row in sheet.iter_rows(min_row=1, max_row=sheet.max_row):
        if row[0].value is None:  # Blank row
            if current_block:
                blocks.append(current_block)
                current_block = []
        else:
            current_block.append(row)
    if current_block:
        blocks.append(current_block)

    # Sort each block by column D in descending order
    for block in blocks:
        sorted_block = sorted(block, key=lambda x: x[3].value, reverse=True)
        for i, row in enumerate(sorted_block):
            for j, cell in enumerate(row):
                sheet.cell(row=i + 1, column=j + 1, value=cell.value)

    # Ensure exactly one blank row between blocks
    block_index = 0
    for i in range(1, sheet.max_row + 1):
        if i > 1 and sheet.cell(row=i, column=1).value is None:
            block_index += 1
            if block_index < len(blocks):
                for j in range(1, sheet.max_column + 1):
                    sheet.cell(row=i, column=j, value=None)

    # Apply formatting to columns D-F
    for row in sheet.iter_rows(min_col=4, max_col=6):
        for cell in row:
            if cell.data_type == 'n':
                cell.font = Font(bold=True)
                cell.alignment = Alignment(horizontal='center')

    # Save the workbook
    wb.save('output.xlsx')

