from openpyxl import load_workbook
from openpyxl.styles import Alignment, Font, Color
from openpyxl.utils import get_column_letter

# Load the workbook
wb = load_workbook('input.xlsx')
collection_sheet = wb['COLLECTION']

# Function to get all data from sheets
def get_all_data():
    data = []
    for sheet_name in wb.sheetnames:
        if sheet_name == 'COLLECTION':
            continue
        sheet = wb[sheet_name]
        for row in sheet.iter_rows(min_row=2, values_only=True):
            if row:
                data.append(row)
    return data

# Function to process data and aggregate by TY and OR
def process_data(data):
    aggregated = {}
    for row in data:
        item, br, ty, or_, sale, ret = row
        key = (ty, or_)
        if key not in aggregated:
            aggregated[key] = {'ITEM': item, 'BR': br, 'TY': ty, 'OR': or_, 'SALE': 0, 'RET': 0}
        aggregated[key]['SALE'] += sale if sale is not None else 0
        aggregated[key]['RET'] += ret if ret is not None else 0
    return aggregated.values()

# Function to format values
def format_value(value):
    if value is None:
        return '-'
    if value < 0:
        return f'{-abs(value)}'  # Negative values as text with negative sign
    return str(value)

# Function to apply formatting to the collection sheet
def format_collection_sheet(data):
    for i, row in enumerate(data, start=2):
        for j, value in enumerate(row):
            cell = collection_sheet.cell(row=i, column=j+1)
            cell.value = value
            # Apply alignment
            if j in [0, 1, 2, 3]:  # Columns A, B, C, D
                cell.alignment = Alignment(horizontal='left')
            else:  # Columns E, F, G
                cell.alignment = Alignment(horizontal='right')
            # Apply font
            cell.font = Font(name='Calibri', size=11, bold=False)
            # Apply color for negative values
            if j == 5 and value < 0:
                cell.fill = openpyxl.styles.PatternFill(start_color='FF0000', end_color='FF0000', fill_type='solid')
            elif j == 5 and value == 0:
                cell.value = '0'
            elif j == 5 and value is None:
                cell.value = '-'
            elif j == 6:
                cell.value = format_value(value - (row[5] if row[5] is not None else 0))
                cell.font = Font(name='Calibri', size=11, bold=False)
                if cell.value.startswith('-'):
                    cell.fill = openpyxl.styles.PatternFill(start_color='FF0000', end_color='FF0000', fill_type='solid')

# Get all data from sheets
all_data = get_all_data()

# Process data and aggregate
aggregated_data = process_data(all_data)

# Format the collection sheet
format_collection_sheet(aggregated_data)

# Save the workbook
wb.save('output.xlsx')
