from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Extract the scores from rows 1 to 3 (rows 1, 2, 3 in the sheet)
scores = []
for row in ws.iter_rows(min_row=1, max_row=3, min_col=2, max_col=5):
    scores.append([cell.value for cell in row])

# Flatten the scores into a single list
flat_scores = [score for row in scores for score in row]

# Count the frequency of each score
from collections import Counter
score_counts = Counter(flat_scores)

# Find the highest score
highest_score = max(flat_scores)

# Determine how many people have the highest score
num_top = sum(1 for score in flat_scores if score == highest_score)

# Assign points based on the number of people with the highest score
points = {}
if num_top == 1:
    points = {i: 6 for i in range(len(flat_scores)) if flat_scores[i] == highest_score}
elif num_top == 2:
    points = {i: 3 for i in range(len(flat_scores)) if flat_scores[i] == highest_score}
elif num_top == 3:
    points = {i: 2 for i in range(len(flat_scores)) if flat_scores[i] == highest_score}
else:
    points = {i: 0 for i in range(len(flat_scores))}

# Write the computed values to the answer range (B5:E7)
for i, cell in enumerate(ws['B5:E7'], start=0):
    cell.value = points.get(i, 0)

# Save the workbook
wb.save('output.xlsx')
